{"content": """"Model Router — Intelligent routing between local, cloud, and rule-based inference.

Implements Cactus Prize logic: routes sensitive data to local, complex
queries to cloud, and simple queries to rule-based responses.
"""

from dataclasses import dataclass, field
from enum import Enum
from typing import Any

from src.config import settings


class RouteTarget(str, Enum):
    LOCAL = "local"        # Gemma 4 27B via Ollama
    CLOUD = "cloud"        # Gemini API
    RULES = "rules"        # Template/rule-based (zero latency)


@dataclass
class RouteDecision:
    target: RouteTarget
    reason: str
    confidence: float = 1.0
    metadata: dict[str, Any] = field(default_factory=dict)


class ModelRouter:
    """Routes inference requests to the best available backend."""

    # Patterns that indicate sensitive/PII data — always route to local
    PII_PATTERNS = [
        "social security", "ssn", "medicaid", "medicare",
        "address is", "phone number", "date of birth",
        "medical record", "diagnosis", "prescription",
        "child's name", "my daughter", "my son",
        "credit card", "bank account",
    ]

    # Keywords that indicate crisis/urgent situations
    CRISIS_PATTERNS = [
        "emergency", "urgent", "immediately", "right now",
        "hurt", "danger", "bleeding", "can't breathe",
        "suicidal", "self-harm",
    ]

    # Very simple queries that don't need an LLM
    SIMPLE_PATTERNS = [
        "what time", "what day", "hello", "hi", "thanks",
        "goodbye", "ok", "yes", "no",
    ]

    def __init__(self):
        self.decisions: list[RouteDecision] = []

    def decide(
        self,
        prompt: str,
        context: dict[str, Any] | None = None,
        local_available: bool = False,
    ) -> RouteDecision:
        """Decide where to route a request.

        Priority:
        1. Crisis → LOCAL (immediate, works offline)
        2. Sensitive/PII → LOCAL (privacy)
        3. No connectivity → RULES (fallback)
        4. Simple query → RULES (fast)
        5. Default → CLOUD (richer responses)
        """
        ctx = context or {}
        prompt_lower = prompt.lower()

        # 1. Crisis detection → LOCAL
        if any(pattern in prompt_lower for pattern in self.CRISIS_PATTERNS):
            return self._record(RouteDecision(
                target=RouteTarget.LOCAL,
                reason="Crisis keywords detected — routing to local for immediate offline response",
                confidence=0.95,
            ))

        # 2. High priority from context → LOCAL
        if ctx.get("priority", 0) >= 4:
            return self._record(RouteDecision(
                target=RouteTarget.LOCAL,
                reason=f"High priority ({ctx['priority']}) — routing to local",
                confidence=0.90,
            ))

        # 3. PII/sensitive data → LOCAL
        if any(pattern in prompt_lower for pattern in self.PII_PATTERNS):
            return self._record(RouteDecision(
                target=RouteTarget.LOCAL,
                reason="Sensitive/PII content detected — routing to local for privacy",
                confidence=0.85,
            ))

        # 4. Explicit sensitive context flag → LOCAL
        if ctx.get("sensitive"):
            return self._record(RouteDecision(
                target=RouteTarget.LOCAL,
                reason="Context marked as sensitive — routing to local",
                confidence=0.80,
            ))

        # 5. No local available AND no connectivity → RULES
        if not local_available and not self._has_connectivity():
            return self._record(RouteDecision(
                target=RouteTarget.RULES,
                reason="No local model and no connectivity — fallback to rules",
                confidence=0.70,
            ))

        # 6. Simple query → RULES
        if len(prompt_lower.split()) <= 3 and any(
            pattern in prompt_lower for pattern in self.SIMPLE_PATTERNS
        ):
            return self._record(RouteDecision(
                target=RouteTarget.RULES,
                reason="Simple query — routing to rules for zero-latency response",
                confidence=0.60,
            ))

        # 7. Default: prefer local if available, else cloud
        if local_available:
            return self._record(RouteDecision(
                target=RouteTarget.LOCAL,
                reason="Local model available — defaulting to local",
                confidence=0.70,
            ))

        return self._record(RouteDecision(
            target=RouteTarget.CLOUD,
            reason="Default route — cloud model for best quality",
            confidence=0.65,
        ))

    def _has_connectivity(self) -> bool:
        """Check if cloud connectivity is available."""
        if settings.GOOGLE_API_KEY and settings.GOOGLE_API_KEY != "dev-key-override-in-prod":
            return True
        return False

    def _record(self, decision: RouteDecision) -> RouteDecision:
        self.decisions.append(decision)
        # Keep only last 100 decisions
        if len(self.decisions) > 100:
            self.decisions = self.decisions[-100:]
        return decision

    def get_decision_log(self, limit: int = 20) -> list[dict[str, Any]]:
        """Return recent routing decisions for monitoring."""
        return [
            {
                "target": d.target.value,
                "reason": d.reason,
                "confidence": d.confidence,
            }
            for d in self.decisions[-limit:]
        ]

    def get_stats(self) -> dict[str, int]:
        """Return routing statistics."""
        stats = {"local": 0, "cloud": 0, "rules": 0, "total": len(self.decisions)}
        for d in self.decisions:
            stats[d.target.value] += 1
        return stats
